using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.Parientes;namespace GraphApi.Services.USR.Parientes{    public class ParientesService : IParientesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ParientesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadParientes>> GetParientes(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.vsParientes (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadParientes>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetParientesDynamic(            int? parienteID,            int? usuarioID,            string? nombreUsuario,            string? correoUsuario,            string? nombrePariente,            int? parentescoID,            string? parentesco,            string? telefonoPariente,            string? correoPariente,            bool? esContactoEmergencia,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ParienteID, UsuarioID, NombreUsuario, CorreoUsuario, NombrePariente, ParentescoID, Parentesco, TelefonoPariente, CorreoPariente, EsContactoEmergencia, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.vsParientes (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (parienteID.HasValue)            {                vSql.Append(" AND ParienteID = @ParienteID");                vParameters.Add("ParienteID",parienteID);            }            if (!string.IsNullOrWhiteSpace(nombreUsuario))            {                vSql.Append(" AND NombreUsuario LIKE @NombreUsuario");                vParameters.Add("NombreUsuario",$"%{nombreUsuario}%");            }            if (!string.IsNullOrWhiteSpace(correoUsuario))            {                vSql.Append(" AND CorreoUsuario LIKE @CorreoUsuario");                vParameters.Add("CorreoUsuario",$"%{correoUsuario}%");            }            if (!string.IsNullOrWhiteSpace(nombrePariente))            {                vSql.Append(" AND NombrePariente LIKE @NombrePariente");                vParameters.Add("NombrePariente",$"%{nombrePariente}%");            }            if (!string.IsNullOrWhiteSpace(parentesco))            {                vSql.Append(" AND Parentesco LIKE @Parentesco");                vParameters.Add("Parentesco",$"%{parentesco}%");            }            if (!string.IsNullOrWhiteSpace(telefonoPariente))            {                vSql.Append(" AND TelefonoPariente LIKE @TelefonoPariente");                vParameters.Add("TelefonoPariente",$"%{telefonoPariente}%");            }            if (!string.IsNullOrWhiteSpace(correoPariente))            {                vSql.Append(" AND CorreoPariente LIKE @CorreoPariente");                vParameters.Add("CorreoPariente",$"%{correoPariente}%");            }            if (esContactoEmergencia.HasValue)            {                vSql.Append(" AND EsContactoEmergencia = @EsContactoEmergencia");                vParameters.Add("EsContactoEmergencia", esContactoEmergencia.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadParientes> CreateParientes(clCreateParientes objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.Parientes                (UsuarioID, NombrePariente, ParentescoID, TelefonoPariente, CorreoPariente, EsContactoEmergencia, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@UsuarioID, @NombrePariente, @ParentescoID, @TelefonoPariente, @CorreoPariente, @EsContactoEmergencia, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.UsuarioID,                objInput.NombrePariente,                objInput.ParentescoID,                objInput.TelefonoPariente,                objInput.CorreoPariente,                objInput.EsContactoEmergencia,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ParienteID, UsuarioID, NombreUsuario, CorreoUsuario, NombrePariente, ParentescoID, Parentesco, TelefonoPariente, CorreoPariente, EsContactoEmergencia, bEliminado                FROM usr.vsParientes (NOLOCK)                WHERE ParienteID = @ParienteID;";            var vReadParams = new { ParienteID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadParientes>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Pariente con ID {vNewId}.");            return vCreated;        }        public async Task<clReadParientes?> UpdateParientes(clUpdateParientes objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ParienteID", objInput.ParienteID);            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.NombrePariente is not null)            {                vSets.Add("NombrePariente = @NombrePariente");                vParameters.Add("NombrePariente", objInput.NombrePariente);            }            if (objInput.ParentescoID != null)            {                vSets.Add("ParentescoID = @ParentescoID");                vParameters.Add("ParentescoID", objInput.ParentescoID);            }            if (objInput.TelefonoPariente is not null)            {                vSets.Add("TelefonoPariente = @TelefonoPariente");                vParameters.Add("TelefonoPariente", objInput.TelefonoPariente);            }            if (objInput.CorreoPariente is not null)            {                vSets.Add("CorreoPariente = @CorreoPariente");                vParameters.Add("CorreoPariente", objInput.CorreoPariente);            }            if (objInput.EsContactoEmergencia != null)            {                vSets.Add("EsContactoEmergencia = @EsContactoEmergencia");                vParameters.Add("EsContactoEmergencia", objInput.EsContactoEmergencia);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.Parientes                SET {vSetClause}                WHERE ParienteID = @ParienteID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ParienteID, UsuarioID, NombreUsuario, CorreoUsuario, NombrePariente, ParentescoID, Parentesco, TelefonoPariente, CorreoPariente, EsContactoEmergencia, bEliminado                FROM usr.vsParientes (NOLOCK)                WHERE ParienteID = @ParienteID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadParientes>(sSelect, new {  objInput.ParienteID });        }        public async Task<bool> DeleteParientes(int nParientesID)        {            const string sSql = @"                DELETE FROM usr.Parientes                WHERE ParienteID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nParientesID });            return vAffected > 0;        }    }}